import java.nio.file.*
def srcDir = new File(project.build.directory, 'generated-sources/intention-utils')
def patches = [ // MergeIfsUtils.kt: findExistingEditor() is an IDE-only API for moving the editor caret. // Removing both the import and the usage; the merge transformation still works correctly. [file: 'org/jetbrains/kotlin/idea/codeinsights/impl/base/inspections/MergeIfsUtils.kt', old: 'import org.jetbrains.kotlin.idea.codeinsight.utils.findExistingEditor
', new_: ''], [file: 'org/jetbrains/kotlin/idea/codeinsights/impl/base/inspections/MergeIfsUtils.kt', old: ' element.findExistingEditor()?.caretModel?.moveToOffset(element.startOffset)
', new_: ''], // MergeIfsUtils.kt: safeAs<KtBlockExpression>() generates an UNCHECKED_CAST compiler error in 2.2. // Replace with a regular as? cast wrapped in parentheses to preserve operator precedence. [file: 'org/jetbrains/kotlin/idea/codeinsights/impl/base/inspections/MergeIfsUtils.kt', old: 'import org.jetbrains.kotlin.utils.addToStdlib.safeAs
', new_: ''], [file: 'org/jetbrains/kotlin/idea/codeinsights/impl/base/inspections/MergeIfsUtils.kt', old: 'then.safeAs<KtBlockExpression>()', new_: '(then as? KtBlockExpression)'],
