// KotlinPsiUtils.kt: remove createArgumentWithoutName — conflicting overload with ArgumentUtils.kt. // Both are in package org.jetbrains.kotlin.idea.codeinsight.utils; Kotlin doesn't allow overloads // that differ only in return type. ArgumentUtils.kt version (List<String>) is the one we keep. // Era 253 function body (used after submodule update): [file: 'org/jetbrains/kotlin/idea/codeinsight/utils/KotlinPsiUtils.kt', old: 'fun createArgumentWithoutName(argument: KtValueArgument, isVararg: Boolean = false, isArrayOf: Boolean = false): List<KtValueArgument> {
 if (!argument.isNamed()) return listOf(argument.copied())
 val argumentExpr = argument.getArgumentExpression() ?: return emptyList()
 val psiFactory = KtPsiFactory(argument)
 return when {
 isVararg && argumentExpr is KtCollectionLiteralExpression ->
 argumentExpr.getInnerExpressions().map { psiFactory.createArgument(it) }

 isVararg && argumentExpr is KtCallExpression && isArrayOf ->
 argumentExpr.valueArguments.map { psiFactory.createArgument(it.getArgumentExpression()) }

 else -> listOf(psiFactory.createArgument(argumentExpr, name = null, isVararg))
 }
}
', new_: ''], // KotlinPsiUtils.kt (era 253): remove KtCallExpression.isReferenceToBuiltInEnumFunction — // uses ENUM_STATIC_METHOD_NAMES from EnumUtils.kt which we don't copy (IDE-specific deps). [file: 'org/jetbrains/kotlin/idea/codeinsight/utils/KotlinPsiUtils.kt', old: 'context(_: KaSession)
fun KtCallExpression.isReferenceToBuiltInEnumFunction(): Boolean {
 val calleeExpression = this.calleeExpression ?: return false
 return (calleeExpression as? KtSimpleNameExpression)?.getReferencedNameAsName() in ENUM_STATIC_METHOD_NAMES && calleeExpression.isSynthesizedFunction()
}
', new_: ''], // KotlinPsiUtils.kt (era 253): remove KtCallableReferenceExpression.isReferenceToBuiltInEnumFunction — // calls canBeReferenceToBuiltInEnumFunction() from EnumUtils.kt which we don't copy. [file: 'org/jetbrains/kotlin/idea/codeinsight/utils/KotlinPsiUtils.kt', old: 'context(_: KaSession)
fun KtCallableReferenceExpression.isReferenceToBuiltInEnumFunction(): Boolean {
 return this.canBeReferenceToBuiltInEnumFunction() && this.callableReference.isSynthesizedFunction()
}
